(()=>{
  const root=document.querySelector('[data-living-explorer]'); if(!root)return;
  const ui={search:root.querySelector('[data-archive-search]'),year:root.querySelector('[data-archive-year]'),domain:root.querySelector('[data-archive-domain]'),status:root.querySelector('[data-archive-status]'),grid:root.querySelector('[data-archive-grid]')};
  const collections=[
    {id:'life',label:'מאגר החיים',path:'/knowledge/master-public-record-20260918.json',key:'records'},
    {id:'social',label:'קורפוס חברתי',path:'/knowledge/social-corpus-20260918.json',key:'moments'},
    {id:'universe',label:'מפת מקורות',path:'/knowledge/public-universe-records-20260715.json',key:'records'}
  ];
  const state={collection:'life',records:[],query:'',year:'all',domain:'all'};
  const text=v=>String(v||''); const esc=v=>text(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
  const normalized=(item,source)=>({source,year:text(item.year||item.date||'לא מתוארך').slice(0,4),title:text(item.title||'רשומה ללא כותרת'),summary:text(item.summary||item.relationship||item.object_type||''),platform:text(item.platform||item.publisher||'מקור ציבורי'),type:text(item.kind||item.type||item.object_type||'רשומה'),url:item.url,verification:text(item.verification||item.evidence_tier||'SOURCE PENDING'),metric:item.metric_display||item.metric?.value||Object.entries(item.metrics||{}).filter(([,v])=>v!==null&&v!==undefined).map(([k,v])=>`${k}: ${v}`).join(' · '),domain:text(item.act||item.theme||item.themes?.[0]||'archive')});
  function render(){const query=state.query.toLocaleLowerCase('he');const filtered=state.records.filter(item=>{const hay=[item.title,item.summary,item.platform,item.type,item.domain].join(' ').toLocaleLowerCase('he');return(!query||hay.includes(query))&&(state.year==='all'||item.year===state.year)&&(state.domain==='all'||item.domain===state.domain)}).slice(0,90);ui.status.textContent=`${filtered.length} רשומות מוצגות מתוך ${state.records.length} בשכבת ${collections.find(c=>c.id===state.collection).label}.`;
    ui.grid.innerHTML=filtered.length?filtered.map(item=>`<article class="archive-explorer-card"><small>${esc(item.source)} · ${esc(item.verification)}</small><h3>${esc(item.title)}</h3><p>${esc(item.summary)}</p><div class="archive-explorer-card__meta">${esc(item.year)} · ${esc(item.platform)} · ${esc(item.type)}${item.metric?`<br>${esc(item.metric)}`:''}${item.url?`<br><a href="${esc(item.url)}" target="_blank" rel="noreferrer">פתיחת המקור ↗</a>`:'<br>ללא URL ציבורי ברשומה זו'}</div></article>`).join(''):'<p class="living-explorer__notice">לא נמצאו רשומות לפי הסינון. נסו שנה, תחום או ניסוח אחר.</p>';
  }
  function options(){const years=[...new Set(state.records.map(x=>x.year).filter(y=>/^\d{4}$/.test(y)))].sort().reverse();const domains=[...new Set(state.records.map(x=>x.domain).filter(Boolean))].sort();ui.year.innerHTML='<option value="all">כל השנים</option>'+years.map(x=>`<option>${esc(x)}</option>`).join('');ui.domain.innerHTML='<option value="all">כל התחומים</option>'+domains.map(x=>`<option>${esc(x)}</option>`).join('');}
  async function load(id){state.collection=id;ui.status.textContent='טוען שכבת מקור…';ui.grid.replaceChildren();root.querySelectorAll('[data-archive-collection]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.archiveCollection===id)));const c=collections.find(x=>x.id===id);try{const response=await fetch(c.path,{cache:'no-store'});if(!response.ok)throw new Error(String(response.status));const json=await response.json();state.records=(json[c.key]||[]).map(x=>normalized(x,c.label));state.year='all';state.domain='all';options();render()}catch{ui.status.textContent='טעינת שכבת המקור נכשלה. אפשר לפתוח את קובצי ה־JSON ישירות למטה.';}}
  root.querySelectorAll('[data-archive-collection]').forEach(b=>b.addEventListener('click',()=>load(b.dataset.archiveCollection)));ui.search.addEventListener('input',e=>{state.query=e.target.value;render()});ui.year.addEventListener('change',e=>{state.year=e.target.value;render()});ui.domain.addEventListener('change',e=>{state.domain=e.target.value;render()});load('life');
})();
